package admin

import (
	"fmt"
	"html/template"
	"strconv"
	"strings"
)

func parsePages() *template.Template {
	return template.Must(template.New("pages").Funcs(template.FuncMap{
		"count": count, "size": size, "upper": strings.ToUpper,
	}).Parse(pageTemplates))
}

// count groups thousands so large queue numbers scan at a glance.
func count(n any) string {
	s := fmt.Sprint(n)
	for i := len(s) - 3; i > 0; i -= 3 {
		s = s[:i] + "," + s[i:]
	}
	return s
}

// size renders a byte count in decimal units, matching how Amazon reports storage.
func size(n int64) string {
	if n < 1000 {
		return strconv.FormatInt(n, 10) + " B"
	}
	value, unit := float64(n), 0
	for value >= 1000 && unit < 5 {
		value /= 1000
		unit++
	}
	return strconv.FormatFloat(value, 'f', 1, 64) + " " + [...]string{"B", "kB", "MB", "GB", "TB", "PB"}[unit]
}

const pageTemplates = `
{{define "head"}}<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><link rel="preload" href="/calsans.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/admin.css">{{end}}
{{define "brand"}}<a class="brand" href="/">Immich <span>to</span> Amazon Photos</a>{{end}}
{{define "bar"}}<header class="topbar"><div class="bar">{{template "brand"}}</div></header>{{end}}
{{define "chevron"}}<svg class="chevron" width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m4 6 4 4 4-4"/></svg>{{end}}
{{define "alert-icon"}}<svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" aria-hidden="true"><circle cx="8" cy="8" r="6.25"/><path d="M8 5v3.5M8 11h.01"/></svg>{{end}}
{{define "login"}}<!doctype html><html lang="en"><head>{{template "head"}}<title>Sign in | Immich to Amazon</title></head>
<body class="center"><main class="narrow">{{template "brand"}}<div class="frame"><div class="frame-head"><h1>Sign in</h1><p>Local control for your original-media backups. Use the passphrase from your mounted admin secret.</p></div>
<form class="sheet stack" method="post" action="/login"><input type="hidden" name="csrf" value="{{.CSRF}}">
<label>Admin passphrase <input type="password" name="password" autocomplete="current-password" required autofocus></label><button>Sign in</button></form></div>
<p class="note">Keep this dashboard on localhost or a trusted private network.</p></main></body></html>{{end}}
{{define "index"}}<!doctype html><html lang="en"><head>{{template "head"}}<title>Backup control | Immich to Amazon</title></head>
<body><header class="topbar"><div class="bar">{{template "brand"}}<div class="bar-actions">{{if .Writable}}<a class="button secondary small" href="/accounts/new">Add account</a>{{end}}<form method="post" action="/logout"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="ghost small">Sign out</button></form></div></div></header>
<main><div class="page-title"><h1>Backup control</h1><p>Independent accounts. Original files. No cloud-media deletion.</p></div>
{{if not .Writable}}<p class="notice">Configuration is read-only. Start with an explicit config path and without --account to edit accounts. Account controls remain available.</p>{{end}}
{{range .Accounts}}{{$health := .Health}}<section class="account" aria-label="Account {{.Account.ID}}">
<div class="frame-head account-head"><div class="identity"><h2>{{.Account.ID}}</h2><p>{{if .Account.Library}}Whole accessible library{{else}}{{len .Account.AlbumIDs}} selected albums{{end}} · albums {{if eq .Account.AlbumMode "all_accessible"}}all accessible{{else if eq .Account.AlbumMode "selected"}}selected{{else}}not mirrored{{end}} · Amazon {{upper .Account.AmazonRegion}}</p></div>
<form class="toolbar" method="post"><input type="hidden" name="csrf" value="{{$.CSRF}}">
{{if .Status.Paused}}<button class="small" formaction="/accounts/{{.Account.ID}}/resume">Resume</button>{{else}}<button class="secondary small" formaction="/accounts/{{.Account.ID}}/pause">Pause</button>{{end}}
<button class="ghost small" formaction="/accounts/{{.Account.ID}}/retry">Retry eligible errors</button><button class="ghost small" formaction="/accounts/{{.Account.ID}}/doctor">Run diagnosis</button>{{if .Account.ManagedWorkflow}}<button class="ghost small" formaction="/accounts/{{.Account.ID}}/workflow-logs">Workflow run logs</button>{{end}}{{if $.Writable}}<a class="button ghost small" href="/accounts/{{.Account.ID}}/edit">Edit</a>{{end}}
</form></div>
<div class="sheet">
<div class="health"><span class="badge {{$health.Tone}}">{{$health.Label}}</span>{{if .Status.LastSuccess}}<span class="since">Last complete reconcile <time>{{.Status.LastSuccess.Format "2006-01-02 15:04:05 MST"}}</time></span>{{end}}</div>
{{if ne .Code "ok"}}<p class="alert" role="status">{{template "alert-icon"}}<span>Status unavailable: <code>{{.Code}}</code>. Check mounted credentials or run diagnosis.</span></p>{{end}}
{{if .Status.Errors}}<div class="alert">{{template "alert-icon"}}<div><strong>Errors requiring attention</strong><dl class="codes">{{range $code, $count := .Status.Errors}}<div><dt><code>{{$code}}</code></dt><dd>{{count $count}}</dd></div>{{end}}</dl></div></div>{{end}}
{{with .Segments}}<svg class="distribution" width="100%" height="8" role="img" aria-label="Share of media by state">{{range .}}{{if .Count}}<rect class="{{.Tone}}" x="{{.Offset}}" width="{{.Width}}" height="8"/>{{end}}{{end}}</svg>
<ul class="legend">{{range .}}{{if .Count}}<li><i class="{{.Tone}}"></i><b>{{count .Count}}</b> {{.Label}}</li>{{end}}{{end}}</ul>{{else}}<p class="empty-queue">Nothing has been queued yet. The first scan fills this in.</p>{{end}}
<dl class="facts" aria-label="Schedule"><div><dt>Work remaining</dt><dd>{{if .Status.WorkRemaining}}ready to run{{else}}none ready to run{{end}}</dd></div><div><dt>Next attempt</dt><dd>{{if .Status.NextAttempt}}<time datetime="{{.Status.NextAttempt.Format "2006-01-02T15:04:05Z07:00"}}">{{.Status.NextAttempt.Format "2006-01-02 15:04:05 MST"}}</time>{{else}}none scheduled{{end}}</dd></div><div><dt>Incremental scan</dt><dd>{{if .Status.IncrementalScanning}}in progress{{else}}idle{{end}}</dd></div><div><dt>Last incremental reconcile</dt><dd>{{if .Status.LastIncremental}}<time datetime="{{.Status.LastIncremental.Format "2006-01-02T15:04:05Z07:00"}}">{{.Status.LastIncremental.Format "2006-01-02 15:04:05 MST"}}</time>{{else}}not yet completed{{end}}</dd></div>{{if not .Status.LastSuccess}}<div><dt>Last complete reconcile</dt><dd>not yet completed</dd></div>{{end}}<div><dt>Scopes scanning</dt><dd>{{.Status.Scanning}}</dd></div>{{if .Status.TransferWindow}}<div><dt>Transfer window</dt><dd>{{.Status.TransferWindow.Timezone}} {{.Status.TransferWindow.Start}}–{{.Status.TransferWindow.End}} · {{if .Status.TransferWindow.Open}}open{{else}}closed{{end}}</dd></div>{{if .Status.TransferWindow.NextOpening}}<div><dt>Next opening</dt><dd><time datetime="{{.Status.TransferWindow.NextOpening.Format "2006-01-02T15:04:05Z07:00"}}">{{.Status.TransferWindow.NextOpening.Format "2006-01-02 15:04 MST"}}</time></dd></div>{{end}}{{if .Status.DeferralReason}}<div><dt>Deferral reason</dt><dd><code>{{.Status.DeferralReason}}</code></dd></div>{{end}}{{end}}</dl>
</div>
<div class="accordion">
<details><summary>Queue states<span>{{count .Status.Skipped}} skipped</span>{{template "chevron"}}</summary><dl class="rows" aria-label="Media queue"><div><dt>Confirmed</dt><dd>{{count .Status.Confirmed}}</dd></div><div><dt>Existing</dt><dd>{{count .Status.Existing}}</dd></div><div><dt>Pending</dt><dd>{{count .Status.Pending}}</dd></div><div><dt>Staged</dt><dd>{{count .Status.Staged}}</dd></div><div><dt>Running</dt><dd>{{count .Status.Running}}</dd></div><div><dt>Deferred</dt><dd>{{count .Status.Deferred}}</dd></div><div><dt>Unconfirmed</dt><dd>{{count .Status.Unconfirmed}}</dd></div><div><dt>Failed</dt><dd>{{count .Status.Failed}}</dd></div><div><dt>Blocked</dt><dd>{{count .Status.Blocked}}</dd></div><div><dt>Skipped</dt><dd>{{count .Status.Skipped}}</dd></div><div><dt>Deletion pending</dt><dd>{{count .Status.DeletePending}}</dd></div><div><dt>In Amazon trash</dt><dd>{{count .Status.Deleted}}</dd></div></dl>{{if .Status.Exclusions}}<h3>Excluded assets by reason</h3><dl class="rows">{{range $code, $count := .Status.Exclusions}}<div><dt><code>{{$code}}</code></dt><dd>{{count $count}}</dd></div>{{end}}</dl>{{end}}</details>
<details><summary>Albums and events<span>{{.Status.AlbumsActive}} albums active</span>{{template "chevron"}}</summary><dl class="rows" aria-label="Event, album and association backlog"><div><dt>Events pending</dt><dd>{{.Status.EventsPending}}</dd></div><div><dt>Events failed</dt><dd>{{.Status.EventsFailed}}</dd></div><div><dt>Albums active</dt><dd>{{.Status.AlbumsActive}}</dd></div><div><dt>Albums pending</dt><dd>{{.Status.AlbumsPending}}</dd></div><div><dt>Albums failed</dt><dd>{{.Status.AlbumsFailed}}</dd></div><div><dt>Albums unconfirmed</dt><dd>{{.Status.AlbumsUnconfirmed}}</dd></div><div><dt>Albums inaccessible</dt><dd>{{.Status.AlbumsInaccessible}}</dd></div><div><dt>Associations pending</dt><dd>{{.Status.AssociationsPending}}</dd></div><div><dt>Associations failed</dt><dd>{{.Status.AssociationsFailed}}</dd></div><div><dt>Associations unconfirmed</dt><dd>{{.Status.AssociationsUnconfirmed}}</dd></div><div><dt>Live Photo pairs</dt><dd>{{if eq .Status.LivePhotoMode "original_pair"}}{{count .Status.PairsComplete}} complete · {{count .Status.PairsIncomplete}} incomplete{{else}}still only{{end}}</dd></div></dl></details>
<details><summary>Observed storage<span>{{.Status.Usage.State}}</span>{{template "chevron"}}</summary><dl class="rows" aria-label="Observed storage usage"><div><dt>Usage state</dt><dd>{{.Status.Usage.State}}</dd></div><div><dt>Calculated</dt><dd>{{if .Status.Usage.LastCalculated}}<time>{{.Status.Usage.LastCalculated.Format "2006-01-02 15:04 MST"}}</time>{{else}}unknown{{end}}</dd></div>{{if ne .Status.Usage.State "unavailable"}}<div><dt>Photos billable</dt><dd title="{{.Status.Usage.Photo.Billable.Bytes}} bytes">{{size .Status.Usage.Photo.Billable.Bytes}} · {{count .Status.Usage.Photo.Billable.Count}}</dd></div><div><dt>Photos total</dt><dd title="{{.Status.Usage.Photo.Total.Bytes}} bytes">{{size .Status.Usage.Photo.Total.Bytes}} · {{count .Status.Usage.Photo.Total.Count}}</dd></div><div><dt>Videos billable</dt><dd title="{{.Status.Usage.Video.Billable.Bytes}} bytes">{{size .Status.Usage.Video.Billable.Bytes}} · {{count .Status.Usage.Video.Billable.Count}}</dd></div><div><dt>Videos total</dt><dd title="{{.Status.Usage.Video.Total.Bytes}} bytes">{{size .Status.Usage.Video.Total.Bytes}} · {{count .Status.Usage.Video.Total.Count}}</dd></div><div><dt>Other billable</dt><dd title="{{.Status.Usage.Other.Billable.Bytes}} bytes">{{size .Status.Usage.Other.Billable.Bytes}} · {{count .Status.Usage.Other.Billable.Count}}</dd></div><div><dt>Other total</dt><dd title="{{.Status.Usage.Other.Total.Bytes}} bytes">{{size .Status.Usage.Other.Total.Bytes}} · {{count .Status.Usage.Other.Total.Count}}</dd></div>{{end}}<div><dt>Subscription capacity</dt><dd>{{.Status.Usage.Capacity}}</dd></div><div><dt>Prime entitlement</dt><dd>{{.Status.Usage.Entitlement}}</dd></div><div><dt>Video threshold</dt><dd>{{if .Status.Usage.VideoThresholdBytes}}{{size .Status.Usage.VideoThresholdBytes}}{{if .Status.Usage.VideoThresholdExceeded}} · exceeded{{end}}{{else}}not configured{{end}}</dd></div><div><dt>Video hold</dt><dd>{{if .Status.Usage.VideoHold}}on{{else}}off{{end}}</dd></div><div><dt>Quota hold</dt><dd>{{if .Status.Usage.QuotaHold}}on{{else}}off{{end}}</dd></div></dl><p class="note">Observed usage is not a subscription cap, remaining capacity or Prime entitlement. Uploads always use original bytes; no quality or recompression mode exists.</p></details>
<details><summary>Favorites<span>{{if .Status.FavoritesMode}}{{.Status.FavoritesMode}}{{else}}off{{end}}</span>{{template "chevron"}}</summary><dl class="rows" aria-label="Favorites"><div><dt>Authority</dt><dd>{{if .Status.FavoritesAuthority}}{{.Status.FavoritesAuthority}}{{else}}none{{end}}</dd></div><div><dt>Desired</dt><dd>{{.Status.FavoritesDesired}}</dd></div><div><dt>Observed</dt><dd>{{.Status.FavoritesObserved}}</dd></div><div><dt>Applied</dt><dd>{{.Status.FavoritesApplied}}</dd></div><div><dt>Preserved</dt><dd>{{.Status.FavoritesPreserved}}</dd></div><div><dt>Pending</dt><dd>{{.Status.FavoritesPending}}</dd></div><div><dt>Failed</dt><dd>{{.Status.FavoritesFailed}}</dd></div><div><dt>Uncertain</dt><dd>{{.Status.FavoritesUncertain}}</dd></div><div><dt>Unknown</dt><dd>{{.Status.FavoritesUnknown}}</dd></div><div><dt>Conflict</dt><dd>{{.Status.FavoritesConflict}}</dd></div></dl>{{if ne .Status.FavoritesMode "off"}}<p class="note fav-note">Desired is the source wish; observed is the last explicit Amazon <code>settings.favorite</code> value; applied is the last star this service verified it performed. Preserved counts Amazon stars kept because this service did not apply them. <code>star_only</code> never unstars; <code>source_applied</code> clears only stars this service applied; <code>takeover</code> also clears manual stars. <code>shared_target_conflict</code> means two local accounts record contradictory wishes for one shared node, so neither writes.</p>{{end}}</details>
<details><summary>Transfer and retry<span>{{if .Status.BytesPerSecond}}{{size .Status.BytesPerSecond}}/s cap{{else}}no rate cap{{end}}</span>{{template "chevron"}}</summary><dl class="rows" aria-label="Transfer"><div><dt>Transfer rate cap</dt><dd>{{if .Status.BytesPerSecond}}{{size .Status.BytesPerSecond}}/s{{else}}disabled{{end}}</dd></div><div><dt>Retry attempts</dt><dd>{{.Status.MaxAttempts}}</dd></div><div><dt>Backoff ceiling</dt><dd>{{.Status.RetryMaxDelayMS}} ms</dd></div><div><dt>Capture date</dt><dd><code>{{.Status.CaptureDate}}</code></dd></div><div><dt>Direct original reads</dt><dd>{{count .Status.Direct.Reads}} · {{size .Status.Direct.BytesAvoided}}</dd></div><div><dt>Immich API reads</dt><dd>{{size .Status.Direct.APIBytes}}</dd></div>{{range $reason, $count := .Status.Direct.Fallbacks}}<div><dt>Fallback <code>{{$reason}}</code></dt><dd>{{$count}}</dd></div>{{end}}{{range $reason, $count := .Status.Direct.Failures}}<div><dt>Failure <code>{{$reason}}</code></dt><dd>{{$count}}</dd></div>{{end}}</dl><p class="note">The rate cap counts source-download and destination-upload bytes together per account; metadata traffic is not counted. Retry preserves uncertain writes and manual pauses: an Unconfirmed write is reconciled, never re-posted.</p></details>
<details><summary>Scope and workflow<span>{{range $i, $media := .Policy.MediaTypes}}{{if $i}}, {{end}}{{$media}}{{end}}</span>{{template "chevron"}}</summary><dl class="rows" aria-label="Managed workflow"><div><dt>Max original</dt><dd>{{if .Policy.MaxOriginalBytes}}{{size .Policy.MaxOriginalBytes}}{{else}}unlimited{{end}}</dd></div><div><dt>RAW</dt><dd>{{if .Policy.SkipRAW}}skipped{{else}}included{{end}}</dd></div><div><dt>Archive</dt><dd>{{if .Policy.ArchivedIncluded}}included{{else}}excluded{{end}}</dd></div><div><dt>Excluded tags</dt><dd>{{len .Policy.ExcludedTags}}</dd></div><div><dt>Workflow</dt><dd>{{if .Status.Workflow}}{{.Status.Workflow}}{{else if .Account.ManagedWorkflow}}requested (pending first cycle){{else}}not requested{{end}}</dd></div>{{if .Status.WorkflowCode}}<div><dt>Workflow notice</dt><dd><code>{{.Status.WorkflowCode}}</code></dd></div>{{end}}<div><dt>Periodic polling</dt><dd>always enabled</dd></div></dl><p class="note">Filters never delete media, remove album membership or authorize trash.</p></details>
{{if $.Writable}}<details class="danger-zone"><summary>Remove this account{{template "chevron"}}</summary><p class="note">Stops scheduling this account. Local history and cloud media are preserved.</p><form method="post" action="/accounts/{{.Account.ID}}/remove"><input type="hidden" name="csrf" value="{{$.CSRF}}"><button class="danger small">Remove account from configuration</button></form></details>{{end}}
</div>
</section>{{else}}<section class="frame empty"><div class="sheet"><h2>Your first backup starts here.</h2><p>Add an Immich source, choose an explicit album scope, and connect an Amazon Photos destination using mounted secret files.</p>{{if .Writable}}<a class="button" href="/accounts/new">Configure first account</a>{{end}}</div></section>{{end}}{{if .Orphans}}<section class="frame" aria-label="Workflow cleanup"><div class="frame-head"><h2>Workflow cleanup needs attention</h2><p>These owned workflows belong to accounts that are no longer configured. Re-add the account with its mounted Workflow credential and set <code>managed_workflow: false</code>, then run <code>workflow remove --apply</code>.</p></div><dl class="sheet rows">{{range .Orphans}}<div><dt>{{.Account}}</dt><dd>{{.State}} <code>{{.Code}}</code></dd></div>{{end}}</dl></section>{{end}}
<footer>Refresh this page for current durable queue counts. Remote failures do not change local readiness.</footer></main></body></html>{{end}}
{{define "editor"}}<!doctype html><html lang="en"><head>{{template "head"}}<title>Account | Immich to Amazon</title></head><body>{{template "bar"}}<main class="editor">
<nav><a href="/">Back to overview</a></nav><h1>Account settings</h1><p>Source and destination credentials stay in separate mounted files. Enter paths, never secret values.</p>
<form class="stack" method="post" action="/accounts/save"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="original_id" value="{{.Original}}">
<label>Account ID <input name="id" value="{{.Account.ID}}" pattern="[a-zA-Z0-9][a-zA-Z0-9_-]{0,127}" {{if .Original}}readonly{{end}} required aria-describedby="identity-note"></label><p class="note" id="identity-note">Stable, unique ID. Use a new ID to connect different cloud identities.</p>
<fieldset><legend>Source / Immich</legend><div class="stack">
<label>Server URL <input type="url" name="immich_url" value="{{.Account.ImmichURL}}" placeholder="https://photos.example.net" required></label>
<label>API key mounted file <input name="key_file" value="{{.Account.APIKeyFile}}" placeholder="/run/secrets/immich_key" required></label>
<div><button class="secondary" formaction="/accounts/discover" formnovalidate>List visible albums</button></div>
{{if .Albums}}<div class="album-list"><p>Add albums to the selection below:</p>{{range .Albums}}<label class="check"><input type="checkbox" name="album_id" value="{{.ID}}"><span>{{.Name}} <small>{{.Count}} assets</small></span></label>{{end}}</div>{{end}}
<label>Selected album IDs <textarea name="album_ids" rows="4" aria-describedby="scope-note">{{range .Account.AlbumIDs}}{{.}}
{{end}}</textarea></label><p class="note" id="scope-note">One ID per line, or comma-separated. Choose albums OR explicitly enable the whole library, never both.</p>
<label class="check"><input type="checkbox" name="library" {{if .Account.Library}}checked{{end}}><span>Explicitly sync the whole accessible library</span></label>
</div></fieldset><fieldset><legend>Eligibility filters</legend><div class="stack">
<p class="note">Filters choose what may be uploaded. They never delete media, remove album membership, or authorize trash. Source-hidden, trashed, offline and unsupported assets stay excluded regardless.</p>
<div class="actions"><label class="check"><input type="checkbox" name="media_image" {{if .Policy.Includes "image"}}checked{{end}}><span>Images</span></label><label class="check"><input type="checkbox" name="media_video" {{if .Policy.Includes "video"}}checked{{end}}><span>Videos</span></label></div>
<label>Maximum original size in bytes <input type="number" name="max_original_bytes" min="0" step="1" value="{{if .Policy.MaxOriginalBytes}}{{.Policy.MaxOriginalBytes}}{{end}}" placeholder="unlimited" aria-describedby="size-note"></label><p class="note" id="size-note">Zero or empty means no limit. When a limit is set, an unknown original size is excluded until the source reports it.</p>
<label class="check"><input type="checkbox" name="skip_raw" {{if .Policy.SkipRAW}}checked{{end}}><span>Skip camera RAW originals (documented extension list)</span></label>
<label class="check"><input type="checkbox" name="include_archived" {{if .Policy.ArchivedIncluded}}checked{{end}}><span>Include archived originals</span></label>
<label>Excluded tag IDs <textarea name="excluded_tags" rows="3" aria-describedby="tag-note">{{range .Policy.ExcludedTags}}{{.}}
{{end}}</textarea></label><p class="note" id="tag-note">Stable Immich tag UUIDs, one per line or comma-separated. If the source omits tag provenance, affected assets are excluded rather than assumed untagged.</p>
<label>Live Photo mode <select name="live_photo_mode" aria-describedby="live-photo-note"><option value="still_only" {{if ne .Account.LivePhotoMode "original_pair"}}selected{{end}}>Still only (default)</option><option value="original_pair" {{if eq .Account.LivePhotoMode "original_pair"}}selected{{end}}>Original pair (still and hidden MOV)</option></select></label><p class="note" id="live-photo-note">Original pair backs up the hidden MOV companion Immich reports for an included still as a second, independent original with its own hash and Node. Nothing is muxed, converted or paired remotely; a missing or ineligible companion is reported as <code>pair_incomplete</code>. Switching modes never re-uploads, overwrites or trashes an existing Node.</p>
</div></fieldset><fieldset><legend>Transfer window</legend><div class="stack">
<label>IANA timezone <input name="transfer_timezone" value="{{with .Account.TransferWindow}}{{.Timezone}}{{end}}" placeholder="America/New_York" aria-describedby="window-note"></label>
<label>Daily start (HH:MM) <input name="transfer_window_start" value="{{with .Account.TransferWindow}}{{.Start}}{{end}}" placeholder="23:00"></label>
<label>Daily end (HH:MM) <input name="transfer_window_end" value="{{with .Account.TransferWindow}}{{.End}}{{end}}" placeholder="06:00"></label>
<p class="note" id="window-note">Leave all three empty for continuous transfers. Times are local to the timezone; a window may cross midnight. Only new uploads pause: metadata checks and album reconciliation continue, and an upload already running finishes. A window change applies without restarting.</p>
</div></fieldset><fieldset><legend>Retry tuning (optional)</legend><div class="stack">
<label>Maximum attempts per item <input type="number" min="1" max="10" name="retry_max_attempts" value="{{with .Account.Retry}}{{if .MaxAttempts}}{{.MaxAttempts}}{{end}}{{end}}" placeholder="5" aria-describedby="retry-note"></label>
<label>Backoff ceiling <input name="retry_max_delay" value="{{with .Account.Retry}}{{.MaxDelay}}{{end}}" placeholder="30s" aria-describedby="retry-note"></label>
<p class="note" id="retry-note">Leave empty for the conservative defaults (5 attempts, 30s ceiling). Bounds are 1–10 attempts and 1s–5m. A server Retry-After still wins. Tuning only shortens or lengthens definite-failure retries: an Unconfirmed write is reconciled by re-reading the target before any new POST, regardless of this setting.</p>
</div></fieldset><fieldset><legend>Destination / Amazon Photos</legend><div class="stack">
<label>Region code <input name="region" value="{{.Account.AmazonRegion}}" placeholder="us" required aria-describedby="region-note"></label><p class="note" id="region-note">Use your actual account region; no region is selected automatically. Run diagnosis to inspect compatibility evidence.</p>
<label>Cookie mounted file <input name="cookie_file" value="{{.Account.CookieFile}}" placeholder="/run/secrets/amazon_cookie" required></label>
<label>Video usage advisory threshold (bytes) <input type="number" min="0" name="video_usage_threshold_bytes" value="{{.Account.VideoUsageThresholdBytes}}" aria-describedby="threshold-note"></label><p class="note" id="threshold-note">Optional user budget compared with observed billable video bytes. Zero disables it. This is not a provider quota or remaining-capacity estimate.</p>
<label class="check"><input type="checkbox" name="hold_videos_at_threshold" {{if .Account.HoldVideosAtThreshold}}checked{{end}}><span>Hold new video uploads at or above the advisory threshold (photos continue; original files stay queued or staged)</span></label>
<label>Album mirroring <select name="album_sync_mode">
<option value="off" {{if eq .Account.AlbumMode "off"}}selected{{end}}>Off</option>
<option value="selected" {{if eq .Account.AlbumMode "selected"}}selected{{end}}>Selected albums only</option>
<option value="all_accessible" {{if eq .Account.AlbumMode "all_accessible"}}selected{{end}}>All accessible albums</option>
</select></label>
<label>Favorites <select name="favorites"><option value="off" {{if or (eq .Account.Favorites "") (eq .Account.Favorites "off")}}selected{{end}}>Off (no favorite writes)</option><option value="add_only" {{if eq .Account.Favorites "add_only"}}selected{{end}}>Add only (star verified nodes, never unstar)</option><option value="mirror" {{if eq .Account.Favorites "mirror"}}selected{{end}}>Mirror (also clear stars this service applied)</option></select></label>
<label class="check"><input type="checkbox" name="favorites_takeover" {{if .Account.FavoritesTakeover}}checked{{end}}><span>Take over manual Amazon stars (mirror only; clears stars this service did not apply)</span></label>
<label class="check"><input type="checkbox" name="deletions" {{if .Account.Deletions}}checked{{end}}><span>Propagate source trashing to the Amazon trash (off by default; never permanently deletes)</span></label>
<label>Deletion confirmation <input name="deletions_confirmation" value="{{.Account.DeletionConfirmation}}" autocomplete="off" aria-describedby="deletion-note"><span class="note" id="deletion-note">Enabling propagation requires the exact text ENABLE DELETIONS. Turning it off is never gated.</span></label>
</div></fieldset><fieldset><legend>Managed Immich Workflow (optional)</legend><div class="stack">
<label class="check"><input type="checkbox" name="managed_workflow" {{if .Account.ManagedWorkflow}}checked{{end}}><span>Create one owned native Workflow (never replaces periodic polling)</span></label>
<label>Workflow API key mounted file <input name="workflow_key_file" value="{{.Account.WorkflowAPIKeyFile}}" placeholder="/run/secrets/immich_workflow_key" aria-describedby="workflow-note"></label>
<label>Callback URL <input type="url" name="workflow_callback_url" value="{{.Account.WorkflowCallbackURL}}" placeholder="https://sync.example.net/events/account-id" aria-describedby="workflow-note"></label>
<label>Generated secret mounted file <input name="workflow_secret_file" value="{{.Account.WorkflowSecretFile}}" placeholder="/run/secrets/workflow_secret"></label>
<p class="note" id="workflow-note">Use a separate Immich API key with workflow.read/create/update/delete. The service generates the bearer secret into this file with mode 0600 and only ever updates or removes the Workflow UUID it persisted. Immich 2.x or a missing grant falls back to polling with a notice.</p>
</div></fieldset><div class="actions"><button>Save account</button><a class="button secondary" href="/">Cancel</a></div></form>
</main></body></html>{{end}}
{{define "doctor"}}<!doctype html><html lang="en"><head>{{template "head"}}<title>Diagnosis | Immich to Amazon</title></head><body>{{template "bar"}}<main class="editor"><nav><a href="/">Back to overview</a></nav><h1>Account diagnosis</h1><p>{{.ID}} / <code>{{.Code}}</code></p><p class="notice">Read-only probes. Upload and album-write permissions are not tested.</p><dl class="diagnostics">{{range .Checks}}<dt>{{.Name}}</dt><dd><code>{{.Code}}</code></dd>{{end}}</dl></main></body></html>{{end}}
{{define "workflow-logs"}}<!doctype html><html lang="en"><head>{{template "head"}}<title>Workflow logs | Immich to Amazon</title></head><body>{{template "bar"}}<main class="editor"><nav><a href="/">Back to overview</a></nav><h1>Owned Workflow run diagnostics</h1><p>{{.ID}} / <code>{{.Code}}</code></p><p class="notice">Read-only aggregate of the last 50 runs through the separately authorized Workflow credential. It never shows workflow IDs, URLs, payloads or event data.</p><dl class="diagnostics">{{range .Logs}}<dt>{{.Account}}</dt><dd>completed {{.Completed}} · halted {{.Halted}} · error {{.Error}}{{if .Last}} · last {{.Last}}{{end}}</dd>{{end}}</dl></main></body></html>{{end}}
{{define "error"}}<!doctype html><html lang="en"><head>{{template "head"}}<title>Request not completed | Immich to Amazon</title></head><body class="center"><main class="narrow">{{template "brand"}}<div class="frame" role="alert"><div class="sheet"><h1>Request not completed</h1><p><code>{{.}}</code></p><p>Review your settings and mounted secret files, then try again. No secret values are shown here.</p><a href="/">Back to overview</a></div></div></main></body></html>{{end}}
`
